// BRUTE FORCE DETECTION ENGINE - AcmeToCasino Security SOAR v1.0
//
// State is held in process memory. For multi-instance deployments,
// replace global.bruteForceState reads/writes with HTTP calls to
// an internal Redis cache service node.

const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const ALERT_THRESHOLD = 5;
const BLOCK_THRESHOLD = 10;
const SPRAY_THRESHOLD = 10;

if (!global.bruteForceState) {
  global.bruteForceState = {
    failedLogins: {},
    successAfterFail: {},
    passwordSpray: {},
    sprayTimestamps: {}
  };
}

const state = global.bruteForceState;
const detections = [];
const prune = (arr) => arr.filter(e => (now - e.ts) < WINDOW_MS);

for (const item of $input.all()) {
  const log = item.json;
  const eventType = (log.event_type || log.type || '').toLowerCase();
  const sourceIp  = log.source_ip || log.ip || log.remote_addr || 'unknown';
  const username  = log.username  || log.user || log.account   || 'unknown';
  const success   = log.success === true || log.status === 'success' || log.result === 'ok';
  const timestamp = log.timestamp ? new Date(log.timestamp).getTime() : now;

  if (!['auth', 'login', 'authentication'].includes(eventType)) {
    continue;
  }

  if (state.failedLogins[sourceIp]) {
    state.failedLogins[sourceIp] = prune(state.failedLogins[sourceIp]);
  }

  if (!success) {
    if (!state.failedLogins[sourceIp])   state.failedLogins[sourceIp]   = [];
    if (!state.passwordSpray[sourceIp])  state.passwordSpray[sourceIp]  = new Set();
    if (!state.sprayTimestamps[sourceIp]) state.sprayTimestamps[sourceIp] = [];
    if (!state.successAfterFail[sourceIp]) state.successAfterFail[sourceIp] = { failCount: 0, lastFail: null };

    state.failedLogins[sourceIp].push({ ts: timestamp, username });
    state.successAfterFail[sourceIp].failCount++;
    state.successAfterFail[sourceIp].lastFail = timestamp;
    state.passwordSpray[sourceIp].add(username);
    state.sprayTimestamps[sourceIp].push(timestamp);
    state.sprayTimestamps[sourceIp] = prune(state.sprayTimestamps[sourceIp]);

    const recentFails = state.failedLogins[sourceIp].length;

    if (recentFails >= BLOCK_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'BRUTE_FORCE',
        action: 'BLOCK',
        severity: 'CRITICAL',
        confidence: 0.97,
        source_ip: sourceIp,
        username,
        failed_attempts: recentFails,
        window_minutes: 5,
        timestamp: new Date(now).toISOString(),
        ttl_seconds: 86400,
        details: `${recentFails} failed login attempts from ${sourceIp} in 5 minutes`,
        original_event: log
      }});
    } else if (recentFails >= ALERT_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'BRUTE_FORCE',
        action: 'ALERT',
        severity: 'HIGH',
        confidence: 0.90,
        source_ip: sourceIp,
        username,
        failed_attempts: recentFails,
        window_minutes: 5,
        timestamp: new Date(now).toISOString(),
        ttl_seconds: 86400,
        details: `${recentFails} failed login attempts from ${sourceIp} in 5 minutes`,
        original_event: log
      }});
    }

    const uniqueAccounts = state.passwordSpray[sourceIp].size;
    if (uniqueAccounts >= SPRAY_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'PASSWORD_SPRAY',
        action: 'BLOCK',
        severity: 'CRITICAL',
        confidence: 0.93,
        source_ip: sourceIp,
        unique_accounts_targeted: uniqueAccounts,
        timestamp: new Date(now).toISOString(),
        ttl_seconds: 86400,
        details: `Password spray: ${sourceIp} targeted ${uniqueAccounts} unique accounts`,
        original_event: log
      }});
    }
  } else {
    const entry = state.successAfterFail[sourceIp];
    if (entry && entry.failCount >= ALERT_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'CREDENTIAL_STUFFING',
        action: 'BLOCK',
        severity: 'CRITICAL',
        confidence: 0.92,
        source_ip: sourceIp,
        username,
        prior_failures: entry.failCount,
        timestamp: new Date(now).toISOString(),
        ttl_seconds: 86400,
        details: `Successful login from ${sourceIp} after ${entry.failCount} failures (credential stuffing)`,
        original_event: log
      }});
      state.successAfterFail[sourceIp] = { failCount: 0, lastFail: null };
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// DDoS DETECTION ENGINE - AcmeToCasino Security SOAR v1.0

const now = Date.now();
const WINDOW_MS       = 1000;
const SUSPICIOUS_RPS  = 100;
const BLOCK_RPS       = 500;
const SYN_THRESHOLD   = 1000;
const HTTP_FLOOD_RPS  = 200;
const SLOWLORIS_MS    = 30000;
const SLOWLORIS_BYTES = 512;

if (!global.ddosState) {
  global.ddosState = {
    requestRate: {},
    synHalfOpen: {},
    httpFlood: {},
    connections: {}
  };
}

const state = global.ddosState;
const detections = [];
const prune = (arr, w) => arr.filter(ts => (now - ts) < w);

for (const item of $input.all()) {
  const log        = item.json;
  const eventType  = (log.event_type || log.type || '').toLowerCase();
  const sourceIp   = log.source_ip || log.ip || log.remote_addr || 'unknown';
  const endpoint   = log.endpoint  || log.path || log.url || '/';
  const userAgent  = log.user_agent || log.ua || '';
  const connId     = log.connection_id || `${sourceIp}-${log.port || 0}`;
  const bytesSent  = parseInt(log.bytes_sent || log.bytes || 0, 10);
  const synState   = log.tcp_state || '';

  if (['http', 'request', 'access'].includes(eventType)) {
    if (!state.requestRate[sourceIp]) state.requestRate[sourceIp] = [];
    state.requestRate[sourceIp].push(now);
    state.requestRate[sourceIp] = prune(state.requestRate[sourceIp], WINDOW_MS);
    const rps = state.requestRate[sourceIp].length;

    if (rps >= BLOCK_RPS) {
      detections.push({ json: {
        detection_type: 'DDOS_VOLUMETRIC', action: 'BLOCK', severity: 'CRITICAL',
        confidence: 0.98, source_ip: sourceIp, requests_per_second: rps,
        timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `Volumetric DDoS: ${sourceIp} at ${rps} req/s (block threshold: ${BLOCK_RPS})`,
        original_event: log
      }});
    } else if (rps >= SUSPICIOUS_RPS) {
      detections.push({ json: {
        detection_type: 'DDOS_SUSPICIOUS_RATE', action: 'ALERT', severity: 'HIGH',
        confidence: 0.80, source_ip: sourceIp, requests_per_second: rps,
        timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `Suspicious request rate from ${sourceIp}: ${rps} req/s`,
        original_event: log
      }});
    }

    const floodKey = `${sourceIp}|${endpoint}|${userAgent.substring(0, 64)}`;
    if (!state.httpFlood[floodKey]) state.httpFlood[floodKey] = [];
    state.httpFlood[floodKey].push(now);
    state.httpFlood[floodKey] = prune(state.httpFlood[floodKey], WINDOW_MS);
    const floodRps = state.httpFlood[floodKey].length;
    if (floodRps >= HTTP_FLOOD_RPS) {
      detections.push({ json: {
        detection_type: 'HTTP_FLOOD', action: 'BLOCK', severity: 'CRITICAL',
        confidence: 0.95, source_ip: sourceIp, endpoint, user_agent: userAgent,
        requests_per_second: floodRps, timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `HTTP flood: ${sourceIp} targeting ${endpoint} at ${floodRps} req/s with identical UA`,
        original_event: log
      }});
    }
  }

  if (eventType === 'tcp' || eventType === 'network') {
    if (synState === 'SYN_RCVD' || synState === 'HALF_OPEN') {
      state.synHalfOpen[sourceIp] = (state.synHalfOpen[sourceIp] || 0) + 1;
    } else if (synState === 'ESTABLISHED' || synState === 'CLOSED') {
      state.synHalfOpen[sourceIp] = Math.max(0, (state.synHalfOpen[sourceIp] || 0) - 1);
    }
    if ((state.synHalfOpen[sourceIp] || 0) >= SYN_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'SYN_FLOOD', action: 'BLOCK', severity: 'CRITICAL',
        confidence: 0.96, source_ip: sourceIp,
        half_open_connections: state.synHalfOpen[sourceIp],
        timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `SYN flood: ${state.synHalfOpen[sourceIp]} half-open connections from ${sourceIp}`,
        original_event: log
      }});
    }
  }

  if (eventType === 'connection' || eventType === 'http') {
    if (log.connection_start) {
      state.connections[connId] = { startTs: new Date(log.connection_start).getTime(), bytes: bytesSent, ip: sourceIp };
    } else if (state.connections[connId]) {
      state.connections[connId].bytes += bytesSent;
      const conn = state.connections[connId];
      const duration = now - conn.startTs;
      if (duration > SLOWLORIS_MS && conn.bytes < SLOWLORIS_BYTES) {
        detections.push({ json: {
          detection_type: 'SLOWLORIS', action: 'BLOCK', severity: 'HIGH',
          confidence: 0.88, source_ip: sourceIp, connection_id: connId,
          duration_ms: duration, bytes_sent: conn.bytes,
          timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
          details: `Slowloris: connection from ${sourceIp} open ${Math.round(duration/1000)}s with ${conn.bytes} bytes`,
          original_event: log
        }});
        delete state.connections[connId];
      }
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// SQL INJECTION DETECTION ENGINE - AcmeToCasino Security SOAR v1.0

const sqliPatterns = [
  { pattern: /UNION\s+(ALL\s+)?SELECT/gi,          name: 'UNION_SELECT',         severity: 'CRITICAL', confidence: 0.97 },
  { pattern: /OR\s+['"]?1['"]?\s*=\s*['"]?1/gi,    name: 'BOOLEAN_BLIND_OR',     severity: 'HIGH',     confidence: 0.92 },
  { pattern: /AND\s+['"]?1['"]?\s*=\s*['"]?1/gi,   name: 'BOOLEAN_BLIND_AND',    severity: 'HIGH',     confidence: 0.90 },
  { pattern: /DROP\s+TABLE/gi,                      name: 'DDL_DROP_TABLE',       severity: 'CRITICAL', confidence: 0.99 },
  { pattern: /DELETE\s+FROM/gi,                     name: 'DDL_DELETE_FROM',      severity: 'HIGH',     confidence: 0.85 },
  { pattern: /TRUNCATE\s+TABLE/gi,                  name: 'DDL_TRUNCATE',         severity: 'CRITICAL', confidence: 0.98 },
  { pattern: /;\s*--/g,                             name: 'COMMENT_TERMINATOR',   severity: 'MEDIUM',   confidence: 0.75 },
  { pattern: /;\s*(SELECT|INSERT|UPDATE|DELETE)/gi, name: 'STACKED_QUERY',        severity: 'HIGH',     confidence: 0.88 },
  { pattern: /SLEEP\s*\(\s*\d+\s*\)/gi,            name: 'TIME_BLIND_SLEEP',     severity: 'HIGH',     confidence: 0.93 },
  { pattern: /WAITFOR\s+DELAY/gi,                   name: 'TIME_BLIND_WAITFOR',   severity: 'HIGH',     confidence: 0.95 },
  { pattern: /BENCHMARK\s*\(/gi,                    name: 'TIME_BLIND_BENCHMARK', severity: 'HIGH',     confidence: 0.91 },
  { pattern: /LOAD_FILE\s*\(/gi,                    name: 'OOB_LOAD_FILE',        severity: 'CRITICAL', confidence: 0.96 },
  { pattern: /INTO\s+OUTFILE/gi,                    name: 'OOB_INTO_OUTFILE',     severity: 'CRITICAL', confidence: 0.97 },
  { pattern: /0x[0-9a-fA-F]{8,}/g,                 name: 'HEX_ENCODED_PAYLOAD',  severity: 'MEDIUM',   confidence: 0.72 },
  { pattern: /CHAR\s*\(\s*\d+/gi,                  name: 'CHAR_ENCODING',        severity: 'MEDIUM',   confidence: 0.78 }
];

const BASE64_RE = /^[A-Za-z0-9+/]{20,}={0,2}$/;

function checkBase64(value) {
  try {
    const decoded = Buffer.from(value, 'base64').toString('utf-8');
    for (const p of sqliPatterns) {
      if (p.pattern.test(decoded)) { p.pattern.lastIndex = 0; return { matched: true, pattern: p, decoded }; }
      p.pattern.lastIndex = 0;
    }
  } catch (e) {}
  return { matched: false };
}

const detections = [];

for (const item of $input.all()) {
  const log = item.json;
  const sourceIp = log.source_ip || log.ip || log.remote_addr || 'unknown';
  const endpoint = log.endpoint  || log.path || log.url || '/';
  const method   = log.method || 'GET';
  const timestamp = log.timestamp || new Date().toISOString();

  const candidates = [
    log.query_string, log.body, log.request_body, log.payload,
    ...Object.values(log.params || {}),
    ...Object.values(log.query  || {})
  ].filter(v => typeof v === 'string' && v.length > 0);

  let detected = false;
  for (const value of candidates) {
    if (detected) break;
    for (const p of sqliPatterns) {
      if (p.pattern.test(value)) {
        p.pattern.lastIndex = 0;
        detections.push({ json: {
          detection_type: 'SQL_INJECTION', sub_type: p.name,
          action: p.severity === 'CRITICAL' ? 'BLOCK' : 'ALERT',
          severity: p.severity, confidence: p.confidence,
          source_ip: sourceIp, endpoint, method,
          matched_value: value.substring(0, 200),
          timestamp, ttl_seconds: 86400,
          details: `SQLi [${p.name}] from ${sourceIp} on ${method} ${endpoint}`,
          original_event: log
        }});
        detected = true; break;
      }
      p.pattern.lastIndex = 0;
    }
    if (!detected && BASE64_RE.test(value)) {
      const r = checkBase64(value);
      if (r.matched) {
        detections.push({ json: {
          detection_type: 'SQL_INJECTION', sub_type: 'BASE64_' + r.pattern.name,
          action: 'BLOCK', severity: 'CRITICAL', confidence: 0.94,
          source_ip: sourceIp, endpoint, method,
          encoded_value: value.substring(0, 200),
          decoded_value: r.decoded.substring(0, 200),
          timestamp, ttl_seconds: 86400,
          details: `Base64-encoded SQLi from ${sourceIp} on ${method} ${endpoint}`,
          original_event: log
        }});
        detected = true;
      }
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// XSS DETECTION ENGINE - AcmeToCasino Security SOAR v1.0

const xssPatterns = [
  { pattern: /<script[\s>]/gi,                                          name: 'SCRIPT_TAG',            severity: 'HIGH',   confidence: 0.95 },
  { pattern: /<\/script>/gi,                                           name: 'SCRIPT_CLOSE_TAG',      severity: 'HIGH',   confidence: 0.95 },
  { pattern: /on(?:load|error|click|mouse\w+|key\w+|focus|blur|change|submit|reset|select|unload)\s*=/gi,
                                                                        name: 'EVENT_HANDLER',         severity: 'HIGH',   confidence: 0.90 },
  { pattern: /javascript\s*:/gi,                                        name: 'JAVASCRIPT_URI',        severity: 'HIGH',   confidence: 0.97 },
  { pattern: /vbscript\s*:/gi,                                          name: 'VBSCRIPT_URI',          severity: 'HIGH',   confidence: 0.97 },
  { pattern: /data\s*:[^,]*text\/html/gi,                               name: 'DATA_URI_HTML',         severity: 'MEDIUM', confidence: 0.82 },
  { pattern: /document\.(?:write|writeln|cookie|domain)/gi,             name: 'DOM_WRITE',             severity: 'HIGH',   confidence: 0.88 },
  { pattern: /\.innerHTML\s*=/gi,                                       name: 'INNER_HTML_ASSIGN',     severity: 'HIGH',   confidence: 0.87 },
  { pattern: /eval\s*\(/gi,                                             name: 'EVAL_CALL',             severity: 'HIGH',   confidence: 0.85 },
  { pattern: /setTimeout\s*\(\s*['"`]/gi,                               name: 'SETTIMEOUT_STRING',     severity: 'MEDIUM', confidence: 0.78 },
  { pattern: /&#(?:x[0-9a-f]+|\d+);/gi,                                name: 'HTML_ENTITY_ENCODED',   severity: 'MEDIUM', confidence: 0.72 },
  { pattern: /%3c%73%63%72%69%70%74/gi,                                 name: 'URL_ENCODED_SCRIPT',    severity: 'HIGH',   confidence: 0.94 },
  { pattern: /<svg[^>]*onload/gi,                                       name: 'SVG_ONLOAD',            severity: 'HIGH',   confidence: 0.93 },
  { pattern: /<(?:img|body|input|iframe)[^>]*on\w+\s*=/gi,             name: 'TAG_EVENT_HANDLER',     severity: 'HIGH',   confidence: 0.91 }
];

const detections = [];

for (const item of $input.all()) {
  const log = item.json;
  const sourceIp = log.source_ip || log.ip || log.remote_addr || 'unknown';
  const endpoint = log.endpoint  || log.path || log.url || '/';
  const method   = log.method || 'GET';
  const timestamp = log.timestamp || new Date().toISOString();

  const candidates = [
    log.query_string, log.body, log.request_body, log.payload,
    log.referer, log.user_agent,
    ...Object.values(log.params  || {}),
    ...Object.values(log.query   || {}),
    ...Object.values(log.headers || {})
  ].filter(v => typeof v === 'string' && v.length > 0);

  let detected = false;
  for (const value of candidates) {
    if (detected) break;
    for (const p of xssPatterns) {
      if (p.pattern.test(value)) {
        p.pattern.lastIndex = 0;
        detections.push({ json: {
          detection_type: 'XSS', sub_type: p.name,
          action: p.severity === 'HIGH' ? 'BLOCK' : 'ALERT',
          severity: p.severity, confidence: p.confidence,
          source_ip: sourceIp, endpoint, method,
          matched_value: value.substring(0, 200),
          timestamp, ttl_seconds: 86400,
          details: `XSS [${p.name}] from ${sourceIp} on ${method} ${endpoint}`,
          original_event: log
        }});
        detected = true; break;
      }
      p.pattern.lastIndex = 0;
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// ACCOUNT TAKEOVER DETECTION ENGINE - AcmeToCasino Security SOAR v1.0

const INACTIVITY_DAYS        = 30;
const MULTI_ACCOUNT_THRESHOLD = 3;
const RAPID_WITHDRAW_MINUTES  = 5;
const RAPID_WITHDRAW_AMOUNT   = 500;
const WINDOW_MS               = 60 * 60 * 1000;

if (!global.atoState) {
  global.atoState = {
    loginsByIp: {},
    recentLogins: {},
    withdrawalCheck: {}
  };
}

const state = global.atoState;
const now = Date.now();
const detections = [];

for (const item of $input.all()) {
  const log       = item.json;
  const eventType = (log.event_type || log.type || '').toLowerCase();
  const userId    = log.user_id || log.account_id || log.username || null;
  const sourceIp  = log.source_ip || log.ip || 'unknown';
  const country   = log.country || log.geo_country || log.geoip_country_code || 'XX';
  const timestamp = log.timestamp ? new Date(log.timestamp).getTime() : now;

  if ((eventType === 'login' || eventType === 'auth') && log.success === true && userId) {
    if (!state.loginsByIp[sourceIp]) {
      state.loginsByIp[sourceIp] = { accounts: new Set(), timestamps: [] };
    }
    state.loginsByIp[sourceIp].accounts.add(userId);
    state.loginsByIp[sourceIp].timestamps.push(timestamp);
    state.loginsByIp[sourceIp].timestamps = state.loginsByIp[sourceIp].timestamps
      .filter(ts => (now - ts) < WINDOW_MS);

    const accountCount = state.loginsByIp[sourceIp].accounts.size;
    if (accountCount >= MULTI_ACCOUNT_THRESHOLD) {
      detections.push({ json: {
        detection_type: 'ATO_MULTI_ACCOUNT', action: 'ALERT', severity: 'HIGH',
        confidence: 0.85, source_ip: sourceIp, unique_accounts: accountCount, user_id: userId,
        timestamp: new Date(now).toISOString(), ttl_seconds: 86400,
        details: `Multi-account ATO: ${sourceIp} accessed ${accountCount} accounts within 1 hour`,
        original_event: log
      }});
    }

    const lastLogin = state.recentLogins[userId];
    if (lastLogin) {
      const daysSinceLast = (timestamp - lastLogin.ts) / (1000 * 60 * 60 * 24);
      if (daysSinceLast >= INACTIVITY_DAYS && lastLogin.country !== country && country !== 'XX') {
        detections.push({ json: {
          detection_type: 'ATO_NEW_COUNTRY_INACTIVITY', action: 'ALERT', severity: 'HIGH',
          confidence: 0.83, source_ip: sourceIp, user_id: userId,
          previous_country: lastLogin.country, current_country: country,
          days_inactive: Math.round(daysSinceLast),
          timestamp: new Date(now).toISOString(), ttl_seconds: 86400,
          details: `ATO: user ${userId} from ${country} after ${Math.round(daysSinceLast)}d inactive (was ${lastLogin.country})`,
          original_event: log
        }});
      }
    }
    state.recentLogins[userId] = { ts: timestamp, ip: sourceIp, country };
    state.withdrawalCheck[userId] = timestamp;
  }

  if ((eventType === 'withdrawal' || eventType === 'transaction') && userId) {
    const amount  = parseFloat(log.amount || log.value || 0);
    const loginTs = state.withdrawalCheck[userId];
    if (loginTs) {
      const minsSinceLogin = (timestamp - loginTs) / 60000;
      if (minsSinceLogin <= RAPID_WITHDRAW_MINUTES && amount >= RAPID_WITHDRAW_AMOUNT) {
        detections.push({ json: {
          detection_type: 'ATO_RAPID_WITHDRAWAL', action: 'BLOCK', severity: 'CRITICAL',
          confidence: 0.91, source_ip: sourceIp, user_id: userId,
          amount_usd: amount, minutes_since_login: Math.round(minsSinceLogin * 10) / 10,
          timestamp: new Date(now).toISOString(), ttl_seconds: 86400,
          details: `ATO rapid withdrawal: $${amount} by ${userId} only ${Math.round(minsSinceLogin * 10) / 10} min post-login`,
          original_event: log
        }});
        delete state.withdrawalCheck[userId];
      }
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// BOT DETECTION ENGINE - AcmeToCasino Security SOAR v1.0

const MIN_TIMING_SAMPLES = 10;
const MAX_HUMAN_RPS      = 10;
const CV_THRESHOLD       = 0.05;
const WINDOW_MS          = 60 * 1000;

const KNOWN_BAD_BOTS = [
  'scrapy', 'python-requests', 'go-http-client', 'libwww-perl',
  'masscan', 'nmap', 'sqlmap', 'nikto', 'dirbuster', 'gobuster',
  'wfuzz', 'hydra', 'medusa', 'burpsuite', 'havij', 'acunetix',
  'nessus', 'openvas', 'w3af', 'arachni', 'zgrab', 'shodan'
];

const SUSPICIOUS_UA_PATTERNS = [
  /^$/, /^-$/, /^Mozilla\/[45]\.0$/, /curl\//i, /wget\//i,
  /python/i, /java\//i, /ruby/i, /perl/i, /php/i,
  /bot/i, /spider/i, /crawler/i
];

if (!global.botState) {
  global.botState = { requestTimings: {}, suspiciousCounts: {} };
}

const state = global.botState;
const now = Date.now();
const detections = [];

function cv(values) {
  if (values.length < 2) return 1;
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  if (mean === 0) return 0;
  const variance = values.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / values.length;
  return Math.sqrt(variance) / mean;
}

for (const item of $input.all()) {
  const log       = item.json;
  const eventType = (log.event_type || log.type || 'http').toLowerCase();
  const sourceIp  = log.source_ip || log.ip || log.remote_addr || 'unknown';
  const userAgent = log.user_agent || log.ua || '';
  const timestamp = log.timestamp ? new Date(log.timestamp).getTime() : now;

  if (!['http', 'request', 'access'].includes(eventType)) continue;

  const uaLower = userAgent.toLowerCase();
  const knownBot = KNOWN_BAD_BOTS.find(b => uaLower.includes(b));
  if (knownBot) {
    detections.push({ json: {
      detection_type: 'BOT_KNOWN_SIGNATURE', action: 'BLOCK', severity: 'HIGH',
      confidence: 0.97, source_ip: sourceIp, user_agent: userAgent,
      matched_signature: knownBot, timestamp: new Date(now).toISOString(), ttl_seconds: 86400,
      details: `Known bot/scanner signature [${knownBot}] from ${sourceIp}`,
      original_event: log
    }});
    continue;
  }

  const suspiciousUa = SUSPICIOUS_UA_PATTERNS.find(p => p.test(userAgent));
  if (suspiciousUa) {
    state.suspiciousCounts[sourceIp] = (state.suspiciousCounts[sourceIp] || 0) + 1;
    if (state.suspiciousCounts[sourceIp] >= 3) {
      detections.push({ json: {
        detection_type: 'BOT_SUSPICIOUS_UA', action: 'ALERT', severity: 'MEDIUM',
        confidence: 0.78, source_ip: sourceIp, user_agent: userAgent || '(empty)',
        occurrences: state.suspiciousCounts[sourceIp],
        timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `Suspicious UA pattern from ${sourceIp}: "${userAgent || '(empty)'}"`,
        original_event: log
      }});
    }
    continue;
  }

  if (!state.requestTimings[sourceIp]) state.requestTimings[sourceIp] = [];
  state.requestTimings[sourceIp].push(timestamp);
  state.requestTimings[sourceIp] = state.requestTimings[sourceIp]
    .filter(ts => (now - ts) < WINDOW_MS).sort((a, b) => a - b);

  const tsList = state.requestTimings[sourceIp];
  if (tsList.length >= MIN_TIMING_SAMPLES) {
    const rps = tsList.length / (WINDOW_MS / 1000);
    const intervals = [];
    for (let i = 1; i < tsList.length; i++) intervals.push(tsList[i] - tsList[i - 1]);
    const cvVal = cv(intervals);
    if (cvVal < CV_THRESHOLD && rps > MAX_HUMAN_RPS) {
      detections.push({ json: {
        detection_type: 'BOT_REGULAR_TIMING', action: 'ALERT', severity: 'MEDIUM',
        confidence: 0.82, source_ip: sourceIp, user_agent: userAgent,
        requests_per_second: Math.round(rps * 10) / 10,
        timing_cv: Math.round(cvVal * 1000) / 1000, sample_count: tsList.length,
        timestamp: new Date(now).toISOString(), ttl_seconds: 3600,
        details: `Bot-like timing from ${sourceIp}: ${Math.round(rps)} req/s, CV=${cvVal.toFixed(3)}`,
        original_event: log
      }});
    }
  }
}

if (detections.length === 0) {
  return [{ json: { detection_type: 'NONE', source_ip: 'unknown' } }];
}
return detections;

// SEVERITY CLASSIFICATION + GeoIP ENRICHMENT - AcmeToCasino Security SOAR v1.0
//
// In production, insert a MaxMind GeoIP2 HTTP Request node BEFORE this node.
// Call: GET https://geoip.maxmind.com/geoip/v2.1/city/<ip>
// Auth: Basic <account_id>:<license_key>
// Then pass the response as log.geoip_data.

const KNOWN_MALICIOUS_ASNS = new Set(['AS209103', 'AS60781', 'AS16276', 'AS12876', 'AS14061']);
const HIGH_RISK_COUNTRIES  = new Set(['KP', 'IR', 'SY', 'CU', 'SD']);
const SEVERITY_LEVELS      = ['INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];

const TYPE_SEVERITY_MAP = {
  BRUTE_FORCE: 'HIGH',         CREDENTIAL_STUFFING: 'CRITICAL',
  PASSWORD_SPRAY: 'CRITICAL',  DDOS_VOLUMETRIC: 'CRITICAL',
  DDOS_SUSPICIOUS_RATE: 'HIGH', HTTP_FLOOD: 'CRITICAL',
  SYN_FLOOD: 'CRITICAL',       SLOWLORIS: 'HIGH',
  SQL_INJECTION: 'CRITICAL',   XSS: 'HIGH',
  ATO_MULTI_ACCOUNT: 'HIGH',   ATO_NEW_COUNTRY_INACTIVITY: 'HIGH',
  ATO_RAPID_WITHDRAWAL: 'CRITICAL', BOT_KNOWN_SIGNATURE: 'HIGH',
  BOT_SUSPICIOUS_UA: 'MEDIUM', BOT_REGULAR_TIMING: 'MEDIUM'
};

function promoteOnce(severity) {
  const idx = SEVERITY_LEVELS.indexOf(severity);
  return idx >= 0 && idx < SEVERITY_LEVELS.length - 1
    ? SEVERITY_LEVELS[idx + 1] : severity;
}

const enriched = [];

for (const item of $input.all()) {
  const event = { ...item.json };

  if (!event.severity)  event.severity  = TYPE_SEVERITY_MAP[event.detection_type] || 'MEDIUM';
  if (!event.confidence) event.confidence = 0.75;

  const geoip = event.geoip_data || {
    country_code:  event.country || 'XX',
    country_name:  event.country_name || 'Unknown',
    city:          event.city || 'Unknown',
    asn:           event.asn || 'AS0',
    asn_org:       event.asn_org || 'Unknown',
    is_vpn:        event.is_vpn || false,
    is_tor:        event.is_tor || false,
    is_datacenter: event.is_datacenter || false,
    risk_score:    event.geoip_risk_score || 0
  };

  if (HIGH_RISK_COUNTRIES.has(geoip.country_code)) {
    event.severity   = promoteOnce(event.severity);
    event.confidence = Math.min(event.confidence + 0.05, 1.0);
  }
  if (KNOWN_MALICIOUS_ASNS.has(geoip.asn)) {
    event.severity   = 'CRITICAL';
    event.confidence = Math.min(event.confidence + 0.10, 1.0);
  }
  if (geoip.is_vpn || geoip.is_tor) {
    if (SEVERITY_LEVELS.indexOf(event.severity) < SEVERITY_LEVELS.indexOf('HIGH')) {
      event.severity = 'HIGH';
    }
    const flags = event.threat_intelligence_flags || [];
    if (geoip.is_vpn) flags.push('VPN_EXIT_NODE');
    if (geoip.is_tor) flags.push('TOR_EXIT_NODE');
    event.threat_intelligence_flags = flags;
  }

  event.enrichment = {
    country_code: geoip.country_code, country_name: geoip.country_name,
    city: geoip.city, asn: geoip.asn, asn_org: geoip.asn_org,
    is_vpn: geoip.is_vpn, is_tor: geoip.is_tor, is_datacenter: geoip.is_datacenter,
    risk_score: geoip.risk_score,
    sanctioned_country: HIGH_RISK_COUNTRIES.has(geoip.country_code),
    known_malicious_asn: KNOWN_MALICIOUS_ASNS.has(geoip.asn)
  };

  event.incident_id      = `INC-${Date.now()}-${Math.random().toString(36).substring(2, 8).toUpperCase()}`;
  event.workflow_version = '1.0';
  event.platform         = 'AcmeToCasino';
  event.environment      = $env.ENVIRONMENT || 'production';
  event.deployment_type  = $env.DEPLOYMENT_TYPE || 'aws';

  enriched.push({ json: event });
}

return enriched;

// AWS WAF BLOCK PAYLOAD BUILDER - AcmeToCasino Security SOAR v1.0
//
// Formats the payload consumed by the subsequent AWS WAF HTTP Request node.
// The WAF UpdateIPSet API requires a LockToken obtained from GetIPSet first.
// In production, add a GetIPSet HTTP Request node before this one and pass
// the LockToken through via $json.aws_waf_lock_token.

const results = [];
for (const item of $input.all()) {
  const event = item.json;
  const ip    = event.source_ip;
  if (!ip || ip === 'unknown') {
    results.push({ json: { ...event, waf_action: 'SKIPPED', reason: 'no source IP' } });
    continue;
  }
  const cidr = ip.includes('/') ? ip : `${ip}/32`;
  results.push({ json: {
    ...event,
    waf_action: 'BLOCK_IP',
    aws_waf_payload: {
      Name:           'AcmeToCasino-BlockList',
      Scope:          $env.AWS_WAF_SCOPE || 'REGIONAL',
      IPSetId:        $env.AWS_WAF_IPSET_ID || 'REPLACE_WITH_IPSET_ID',
      IPSetLockToken: event.aws_waf_lock_token || 'REPLACE_WITH_LOCK_TOKEN',
      Addresses:      [cidr],
      operation:      'ADD',
      ttl_seconds:    event.ttl_seconds || 86400,
      reason: `Auto-block: ${event.detection_type} (${event.severity}) - ${event.incident_id}`
    },
    aws_cloudwatch_metric: {
      Namespace:  'AcmeToCasino/Security',
      MetricName: `ThreatBlocked_${event.detection_type}`,
      Value: 1,
      Unit:  'Count',
      Dimensions: [
        { Name: 'Severity',      Value: event.severity },
        { Name: 'DetectionType', Value: event.detection_type }
      ]
    }
  }});
}
return results;

