// ON-PREMISE FIREWALL COMMAND BUILDER - AcmeToCasino Security SOAR v1.0
//
// Builds iptables/nftables commands and ModSecurity rule payloads.
// Set env var USE_NFTABLES=true for nftables-based systems.

const results = [];
for (const item of $input.all()) {
  const event = item.json;
  const ip    = event.source_ip;
  if (!ip || ip === 'unknown') {
    results.push({ json: { ...event, firewall_action: 'SKIPPED' } });
    continue;
  }
  const useNftables = $env.USE_NFTABLES === 'true';
  const expiresAt   = Date.now() + (event.ttl_seconds || 86400) * 1000;
  let command;
  if (useNftables) {
    command = `nft add element inet filter acme_blocklist { ${ip} } && echo 'blocked ${ip} ${event.incident_id}'`;
  } else {
    command = [
      `iptables -I INPUT   -s ${ip} -j DROP`,
      `iptables -I FORWARD -s ${ip} -j DROP`,
      `echo '${ip} ${event.incident_id} ${expiresAt}' >> /var/lib/acme-security/blocked_ips.txt`
    ].join(' && ');
  }
  results.push({ json: {
    ...event,
    firewall_action: 'BLOCK',
    firewall_type:   useNftables ? 'nftables' : 'iptables',
    ssh_command: command,
    modsecurity_rule: {
      phase: 2, action: 'deny', status: 403, ip,
      msg: `AcmeToCasino SOAR: ${event.detection_type} - ${event.incident_id}`
    },
    nginx_block_entry: `deny ${ip}; # ${event.incident_id} expires ${new Date(expiresAt).toISOString()}`
  }});
}
return results;

