// ESCALATION TIMER - AcmeToCasino Security SOAR v1.0
//
// Tracks first-seen timestamp per attacking IP.
// If the same IP is still generating alerts after 10 minutes,
// severity is promoted to CRITICAL and the escalated flag is set,
// which downstream triggers a PagerDuty page.

if (!global.escalationState) {
  global.escalationState = { firstSeen: {} };
}

const state   = global.escalationState;
const ESCALATION_MS = 10 * 60 * 1000;
const now     = Date.now();
const results = [];

for (const item of $input.all()) {
  const event = { ...item.json };
  const ip = event.source_ip;
  if (!ip || ip === 'unknown') { results.push({ json: event }); continue; }

  if (!state.firstSeen[ip]) state.firstSeen[ip] = now;

  const durationMs = now - state.firstSeen[ip];
  event.attack_duration_ms      = durationMs;
  event.attack_duration_minutes = Math.round(durationMs / 60000 * 10) / 10;

  if (durationMs > ESCALATION_MS && event.severity !== 'CRITICAL') {
    event.severity          = 'CRITICAL';
    event.escalated         = true;
    event.escalation_reason = `Attack from ${ip} persisting ${event.attack_duration_minutes} minutes`;
    event.details           = `${event.details} | ESCALATED: ongoing ${event.attack_duration_minutes}min`;
  }

  results.push({ json: event });
}

return results;
